def load_data():
    # Очистка markdown таблицы для Pandas
    cleaned_data = "\n".join([re.sub(r'^\||\|$', '', line) for line in raw_data.strip().split('\n')])
    df = pd.read_csv(io.StringIO(cleaned_data), sep=r'\s*\|\s*', engine='python')
    df = df.drop(0) # Удаляем строку с разделителями (---)
    
    # Преобразуем нужные колонки в числа
    numeric_cols = ['Mode.OnsetTemperature', 'Mode.TemperatureStep', 
                    'SelectivityFactor.Mean', 'SelectivityFactor.StandardDeviation']
    for col in numeric_cols:
        df[col] = pd.to_numeric(df[col], errors='coerce')
        
    return df

# Загружаем данные
df = load_data()

# Получаем уникальные значения кислот для выпадающих списков
acids_from = sorted(df['FattyAcid.From'].dropna().unique())
acids_to = sorted(df['FattyAcid.To'].dropna().unique())

def plot_heatmap():
    fa_from = combo_from.get()
    fa_to = combo_to.get()
    
    if not fa_from or not fa_to:
        messagebox.showwarning("Ошибка", "Выберите обе кислоты!")
        return

    # Фильтруем данные по выбранным кислотам
    subset = df[(df['FattyAcid.From'] == fa_from) & (df['FattyAcid.To'] == fa_to)]
    
    if subset.empty:
        messagebox.showinfo("Пусто", f"Нет данных для пары {fa_from} -> {fa_to}")
        return

    # Создаем сводные таблицы (pivot) для Mean и Std
    pivot_mean = subset.pivot(index='Mode.OnsetTemperature', 
                              columns='Mode.TemperatureStep', 
                              values='SelectivityFactor.Mean')
    
    pivot_std = subset.pivot(index='Mode.OnsetTemperature', 
                             columns='Mode.TemperatureStep', 
                             values='SelectivityFactor.StandardDeviation')

    # Формируем подписи для ячеек в формате "Mean \n ± Std"
    annot_labels = pivot_mean.round(3).astype(str) + "\n± " + pivot_std.round(3).astype(str)
    annot_labels = annot_labels.replace('nan\n± nan', '') # Убираем текст из пустых ячеек

    # Настройка и отрисовка графика
    plt.figure(figsize=(8, 6))
    ax = sns.heatmap(pivot_mean, 
                     annot=annot_labels, 
                     fmt="", 
                     cmap="YlGnBu", # Цветовая палитра (можно заменить на 'viridis', 'coolwarm' и т.д.)
                     cbar_kws={'label': 'SelectivityFactor.Mean'},
                     linewidths=.5)
    
    ax.invert_yaxis() # Переворачиваем ось Y, чтобы температура росла снизу вверх
    plt.title(f"Heatmap: {fa_from} -> {fa_to}", fontsize=14, pad=15)
    plt.xlabel("Mode.TemperatureStep", fontsize=12)
    plt.ylabel("Mode.OnsetTemperature", fontsize=12)
    plt.tight_layout()
    plt.show()

# --- Создание графического интерфейса (Tkinter) ---
root = tk.Tk()
root.title("Выбор кислот для Heatmap")
root.geometry("350x200")
root.eval('tk::PlaceWindow . center') # Центрируем окно

# ИСПРАВЛЕНО ЗДЕСЬ: используем ttk.Frame вместо ttk.Padding
frame = ttk.Frame(root, padding=20)
frame.pack(fill=tk.BOTH, expand=True)

ttk.Label(frame, text="FattyAcid.From:").pack(anchor=tk.W, pady=(0, 5))
combo_from = ttk.Combobox(frame, values=acids_from, state="readonly")
combo_from.pack(fill=tk.X, pady=(0, 15))
if acids_from: combo_from.set(acids_from[0]) # Значение по умолчанию

ttk.Label(frame, text="FattyAcid.To:").pack(anchor=tk.W, pady=(0, 5))
combo_to = ttk.Combobox(frame, values=acids_to, state="readonly")
combo_to.pack(fill=tk.X, pady=(0, 20))
if acids_to: combo_to.set(acids_to[0]) # Значение по умолчанию

btn_plot = ttk.Button(frame, text="Построить Heatmap", command=plot_heatmap)
btn_plot.pack(fill=tk.X, ipady=5)

root.mainloop()